import{_ as t,o,c as a,a5 as r}from"./chunks/framework.QWVCgkrI.js";const g=JSON.parse('{"title":"ビルド構成 — Debug/Development/Release/Shipping・シンボルファイル・PDB・デバッガ","description":"","frontmatter":{"title":"ビルド構成 — Debug/Development/Release/Shipping・シンボルファイル・PDB・デバッガ","study":{"source":"C++ Wiki","status":"published","summary":"最適化・チェック・デバッグ情報・ログの違いから、Debug・Development・Release・Shippingを整理する。","section":"reference","format":"article","domain":"tools"}},"headers":[],"relativePath":"tools/build/build-configurations.md","filePath":"tools/build/build-configurations.md"}'),d={name:"tools/build/build-configurations.md"};function i(n,e,l,s,c,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="ビルド構成-—-debug-development-release-shipping・シンボルファイル・pdb・デバッガ" tabindex="-1">ビルド構成 — Debug/Development/Release/Shipping・シンボルファイル・PDB・デバッガ <a class="header-anchor" href="#ビルド構成-—-debug-development-release-shipping・シンボルファイル・pdb・デバッガ" aria-label="Permalink to &quot;ビルド構成 — Debug/Development/Release/Shipping・シンボルファイル・PDB・デバッガ&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><p>同じソースから「<strong>何を優先するか</strong>」別に複数の成果物を作り分けるのが<strong>ビルド構成 (configuration)</strong>。最適化・チェック・デバッグ情報・ログの4軸の組み合わせです(最適化の中身は → <a href="/study/runtime/cpp-internals/optimization-and-ub.html">コンパイラ最適化・未定義動作の影響・Debug/Release・ゼロコスト抽象化</a>)。</p><h2 id="最適化と診断機能を組み合わせた構成例" tabindex="-1">最適化と診断機能を組み合わせた構成例 <a class="header-anchor" href="#最適化と診断機能を組み合わせた構成例" aria-label="Permalink to &quot;最適化と診断機能を組み合わせた構成例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>構成</th><th>最適化</th><th>assert/チェック</th><th>デバッグ情報</th><th>用途</th></tr></thead><tbody><tr><td><strong>Debug</strong></td><td>なし（例 <code>-O0</code>、<code>/Od</code>）</td><td>開発用チェックを有効化</td><td>あり</td><td>ロジックのステップ実行</td></tr><tr><td><strong>Development</strong></td><td>あり</td><td>開発用チェック、計測などを選んで残す</td><td>あり</td><td>日常の開発・デバッグ</td></tr><tr><td><strong>Release/Profile</strong></td><td>あり</td><td>必要な計測を残すことがある</td><td>必要に応じて生成・保管</td><td>本番相当の性能計測</td></tr><tr><td><strong>Shipping</strong></td><td>出荷向けの設定。LTO の有無は個別に決まる</td><td>出荷に不要な診断機能を除く</td><td>調査用に生成・保管できる</td><td>出荷物</td></tr></tbody></table><p>CMakeには <code>Debug</code>、<code>Release</code>、<code>RelWithDebInfo</code>、<code>MinSizeRel</code> という標準構成があり、Visual Studio などの複数構成ジェネレーターが初期状態で持つ構成の一覧はジェネレーターごとに異なります。最適化したコードの調査には <code>RelWithDebInfo</code> も選べます。Unreal Engine 5.8 には <code>Debug</code>、<code>DebugGame</code>、<code>Development</code>、<code>Shipping</code>、<code>Test</code> があり、使える組み合わせはターゲットで変わります。<code>Shipping</code> でも設定やビルド方法によってデバッグシンボルを生成できます。<a href="https://cmake.org/cmake/help/latest/manual/cmake-buildsystem.7.html#default-and-custom-configurations" target="_blank" rel="noreferrer">CMake の標準構成</a> · <a href="https://dev.epicgames.com/documentation/unreal-engine/build-configurations-reference-for-unreal-engine" target="_blank" rel="noreferrer">Unreal Engine 5.8 のビルド構成</a></p><p>標準の <code>assert</code> が有効かは <code>&lt;cassert&gt;</code> を取り込む時点の <code>NDEBUG</code> で決まります。最適化、構成名、自作の <code>#if GAME_SHIPPING</code> とは別の指定です。<strong>構成間で挙動が変わりすぎると「Shippingでだけ出るバグ」が増える</strong>ので、ゲームロジックの分岐は最小限にします。<a href="https://learn.microsoft.com/en-us/cpp/c-runtime-library/reference/assert-macro-assert-wassert" target="_blank" rel="noreferrer">Microsoft の assert と NDEBUG</a></p><h2 id="シンボルファイル-pdb" tabindex="-1">シンボルファイル(PDB) <a class="header-anchor" href="#シンボルファイル-pdb" aria-label="Permalink to &quot;シンボルファイル(PDB)&quot;">​</a></h2><p>コンパイラは「機械語のアドレス ⇔ ソースの行・変数名」の対応表=<strong>デバッグ情報</strong>を作れます。Windows/MSVCでは<strong>PDBファイル</strong>(別ファイル)、GCC/Clangでは実行ファイル内蔵(-g)や分離(split-dwarf)。</p><ul><li><strong>最適化とデバッグ情報は独立</strong>: <code>-O2 -g</code> は普通(Development構成の実体)。最適化で変数が消える・行が飛ぶのは情報の限界であってPDBの故障ではない</li><li><strong>配布ビルドの調査</strong>では、そのビルドのEXE・DLLと対応するPDBを保管します。ダンプの例外コードやモジュール内の位置を確認し、対応するシンボルで関数名やソースの行を調べられます。公開用と社内用のシンボルは、必要な情報と公開範囲に応じて管理します。<a href="/study/tools/windows/crash-dumps-and-symbols.html">クラッシュダンプとPDB</a></li></ul><h2 id="デバッガ" tabindex="-1">デバッガ <a class="header-anchor" href="#デバッガ" aria-label="Permalink to &quot;デバッガ&quot;">​</a></h2><ul><li>Visual Studioデバッガ(Windows/コンソールの主力)、LLDB(Mac/Clang系)、GDB(Linux/GCC系)</li><li>ブレークポイント、ステップ実行、ウォッチに加え、ゲーム開発では次の機能が役立ちます。 <ul><li><strong>条件付きブレーク</strong>(<code>enemyId == 42</code> のときだけ止まる)/ データブレークポイント(<strong>このアドレスに書き込んだら止まる</strong>——メモリ破壊犯の特定に絶大 → <a href="/study/runtime/memory/memory-bugs.html">メモリバグ</a>)</li><li>クラッシュダンプによる調査では、例外発生時に保存されたスレッドやメモリの情報を開きます。保存される範囲はダンプの種類によって異なります。</li><li>アタッチ: 起動済みのゲームプロセスに後から接続</li></ul></li><li>「printfデバッグは恥」ではない——並行・タイミング系はログの方が有効なことも多い。<strong>両刀</strong>が正解</li></ul><h2 id="c-unityとの対応" tabindex="-1">C#/Unityとの対応 <a class="header-anchor" href="#c-unityとの対応" aria-label="Permalink to &quot;C#/Unityとの対応&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Unity/C#</th><th>C++</th></tr></thead><tbody><tr><td>エディタ再生(Mono/JIT)</td><td>Debug/Development相当</td></tr><tr><td>Development Build</td><td>Unity の Player に開発用機能を含める設定</td></tr><tr><td>Script Debugging</td><td>Development Build と併用して、Player のスクリプトへのデバッガー接続を許可</td></tr><tr><td>IL2CPP の C++ Compiler Configuration</td><td>生成 C++ のコンパイラー構成。Unity 6.3 LTS では Debug、Release、Master</td></tr><tr><td>.pdb/.mdb(スクリプトデバッグ情報)</td><td>PDB(概念同一)</td></tr><tr><td>Cloud Diagnostics / Crashlytics</td><td>クラッシュダンプ+シンボルサーバー</td></tr></tbody></table><p>Unity 6.3 LTS の Development Build と Script Debugging は Player のオプションです。IL2CPP の Debug、Release、Master は生成 C++ の最適化を設定する別項目です。<a href="https://docs.unity3d.com/6000.3/Documentation/ScriptReference/BuildOptions.AllowDebugging.html" target="_blank" rel="noreferrer">Unity 6.3 — BuildOptions.AllowDebugging</a> · <a href="https://docs.unity3d.com/6000.3/Documentation/ScriptReference/Il2CppCompilerConfiguration.html" target="_blank" rel="noreferrer">Unity 6.3 — Il2CppCompilerConfiguration</a></p><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li>「デバッグはエディタでやるもの」— C++では<strong>Shipping相当でだけ出るバグ</strong>(最適化・タイミング・アセット差)を追う技術(ダンプ解析)が必須スキル</li><li>「PDBはビルドの副産物」— Shippingでは<strong>成果物の一部</strong>(保管しないとサポート不能)</li><li>標準の <code>assert</code> を出荷構成で無効にする場合は <code>NDEBUG</code> の設定を確認します。出荷物でも必要な入力検査や失敗処理は、<code>assert</code> の外に実装します(→ <a href="/study/languages/cpp/exceptions.html">契約のassert</a>)。</li></ol><h2 id="実務指針" tabindex="-1">実務指針 <a class="header-anchor" href="#実務指針" aria-label="Permalink to &quot;実務指針&quot;">​</a></h2><ul><li>毎日Developmentで開発し、<strong>週次以上でShippingビルドを起動・テスト</strong>(構成差バグの早期発見)</li><li>ビルドIDをゲーム内に表示(スクショから即座にどのビルドか特定)+ PDBと紐付け</li><li>assertには<strong>メッセージと値</strong>を(<code>assert(index &lt; size &amp;&amp; &quot;enemy index out of range&quot;)</code>)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>4構成の違いを「最適化・チェック・デバッグ情報」の3軸で言えますか。</li><li>ShippingビルドでPDBを生成・保管すべき理由は?</li><li>データブレークポイントはどんなバグに効きますか。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p><a href="/study/tools/build/samples/cmake-demo.html">cmake_demo</a> を Debug と Release でそれぞれビルドし、実行ファイルのサイズと、<code>cmake --build build --verbose</code> で表示するコンパイラーのフラグを比較してください。このサンプルでは <code>assert</code> を呼ばないので、<code>NDEBUG</code> が設定されているかはフラグから読みます。Ninja などでは <code>-DCMAKE_BUILD_TYPE=Debug</code> と <code>Release</code> を別々のビルドフォルダーに指定します。Visual Studio などの場合は、同じビルドフォルダーに対して <code>--config Debug</code> と <code>--config Release</code> を指定します。</p><hr><p>関連項目：<a href="/study/tools/build/build-tools-cmake.html">ビルドツール: CMake</a> / <a href="/study/tools/build/">学習ガイド</a> / <a href="/study/tools/build/build-speed.html">ビルド時間</a></p>',25)])])}const p=t(d,[["render",i]]);export{g as __pageData,p as default};
